model.observation_template:
{% if output.exception_info -%}
<exception>{{output.exception_info}}</exception>
{% endif -%}
<returncode>{{output.returncode}}</returncode>
{% if output.output | length < 10000 -%}
<output>
{{ output.output -}}
</output>
{%- else -%}
<warning>
The output of your last command was too long.
Please try a different command that produces less output.
If you're looking at a file you can try use head, tail or sed to view a smaller number of lines selectively.
If you're using grep or find and it produced too much output, you can use a more selective search pattern.
If you really need to see something from the full command's output, you can redirect output to a file and then search in that file.
</warning>
{%- set elided_chars = output.output | length - 10000 -%}
<output_head>
{{ output.output[:5000] }}
</output_head>
<elided_chars>
{{ elided_chars }} characters elided
</elided_chars>
<output_tail>
{{ output.output[-5000:] }}
</output_tail>
{%- endif -%}

function.arguments:
{"command": "python - <<'PY'
from pathlib import Path
p=Path('vllm/attention/ops/triton_unified_attention.py')
text=p.read_text()
start=text.index('@triton.jit\ndef kernel_unified_attention_2d(')
end=text.index('\n\ndef unified_attention(')
func=text[start:end]
func=func.replace('    stride_k_cache_3: tl.int64,  # int\n', '    stride_k_cache_3: tl.constexpr,  # int\n')
func=func.replace('    stride_v_cache_3: tl.int64,  # int\n', '    stride_v_cache_3: tl.constexpr,  # int\n')
import json
out={'vllm/attention/ops/triton_unified_attention.py': {'kernel_unified_attention_2d': func}}
Path('/prediction.json').write_text(json.dumps(out, indent=4))
print(func)
PY"}

